#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSideBCore: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = SideBCore

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> SideBCore {
        return SideBCore(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: SideBCore) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SideBCore {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: SideBCore, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}




#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSideBCore_lift(_ pointer: UnsafeMutableRawPointer) throws -> SideBCore {
    return try FfiConverterTypeSideBCore.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSideBCore_lower(_ value: SideBCore) -> UnsafeMutableRawPointer {
    return FfiConverterTypeSideBCore.lower(value)
}


public struct AccountInfoRecord {
    public var name: String?
    public var handle: String?
    public var email: String?
    public var thumbnail: String?
    public var channelId: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(name: String?, handle: String?, email: String?, thumbnail: String?, channelId: String?) {
        self.name = name
        self.handle = handle
        self.email = email
        self.thumbnail = thumbnail
        self.channelId = channelId
    }
}



extension AccountInfoRecord: Equatable, Hashable {
    public static func ==(lhs: AccountInfoRecord, rhs: AccountInfoRecord) -> Bool {
        if lhs.name != rhs.name {
            return false
        }
        if lhs.handle != rhs.handle {
            return false
        }
        if lhs.email != rhs.email {
            return false
        }
        if lhs.thumbnail != rhs.thumbnail {
            return false
        }
        if lhs.channelId != rhs.channelId {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(name)
        hasher.combine(handle)
        hasher.combine(email)
        hasher.combine(thumbnail)
        hasher.combine(channelId)
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAccountInfoRecord: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AccountInfoRecord {
        return
            try AccountInfoRecord(
                name: FfiConverterOptionString.read(from: &buf), 
                handle: FfiConverterOptionString.read(from: &buf), 
                email: FfiConverterOptionString.read(from: &buf), 
                thumbnail: FfiConverterOptionString.read(from: &buf), 
                channelId: FfiConverterOptionString.read(from: &buf)
