public enum SideBError {

    
    
    case NetworkError(message: String
    )
    case ParseError(message: String
    )
    case StreamError(message: String
    )
    case DbError(message: String
    )
    case NotFound(message: String
    )
    case Other(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSideBError: FfiConverterRustBuffer {
    typealias SwiftType = SideBError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SideBError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NetworkError(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .ParseError(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .StreamError(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .DbError(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Other(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SideBError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NetworkError(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .ParseError(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .StreamError(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .DbError(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .NotFound(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Other(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


